#!/usr/bin/env python3
from __future__ import annotations
import base64, gzip, subprocess, sys, tempfile
from pathlib import Path

PATCH_GZIP_B64 = """"""

def main() -> int:
    if len(sys.argv) != 2:
        print("usage: apply_v084_project.py <project-root>", file=sys.stderr)
        return 2
    root = Path(sys.argv[1]).resolve()
    if not (root / "app" / "build.gradle").exists():
        raise SystemExit(f"invalid project root: {root}")
    patch = gzip.decompress(base64.b64decode(PATCH_GZIP_B64))
    with tempfile.NamedTemporaryFile(prefix="aurum-v084-", suffix=".patch", delete=False) as tmp:
        tmp.write(patch)
        patch_path = Path(tmp.name)
    try:
        subprocess.run(["patch", "-p1", "--forward", "--batch", "-i", str(patch_path)], cwd=root, check=True)
    finally:
        patch_path.unlink(missing_ok=True)
    print("V084_CPE_PATCH=APPLIED")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
